+const OPERATIONS = {
+  add: (a, b) => a + b,
+  subtract: (a, b) => a - b,
+  multiply: (a, b) => a * b,
+  divide: (a, b) => a / b,
+};
+
+export async function listTools() {
+  return [
+    {
+      name: 'calculate',
+      description: 'Perform a basic arithmetic calculation on two numbers.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          a: { type: 'number', description: 'The first operand.' },
+          b: { type: 'number', description: 'The second operand.' },
+          operation: {
+            type: 'string',
+            enum: ['add', 'subtract', 'multiply', 'divide'],
+            description: 'The arithmetic operation to perform.',
+          },
+        },
+        required: ['a', 'b', 'operation'],
+        additionalProperties: false,
+      },
+    },
+  ];
+}
+
+export async function callTool(name, args) {
+  if (name !== 'calculate') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  validateCalculateArgs(args);
+
+  const { a, b, operation } = args;
+  const fn = OPERATIONS[operation];
+  const result = fn(a, b);
+
+  return {
+    content: [{ type: 'text', text: String(result) }],
+  };
+}
+
+function validateCalculateArgs(args) {
+  const allowed = new Set(['a', 'b', 'operation']);
+  const keys = Object.keys(args);
+
+  for (const key of keys) {
+    if (!allowed.has(key)) {
+      throw new Error(`Unexpected field: ${key}`);
+    }
+  }
+
+  for (const field of ['a', 'b', 'operation']) {
+    if (args[field] === undefined) {
+      throw new Error(`Missing required field: ${field}`);
+    }
+  }
+
+  for (const field of ['a', 'b']) {
+    const value = args[field];
+    if (typeof value !== 'number' || !Number.isFinite(value)) {
+      throw new Error(`Field '${field}' must be a finite number`);
+    }
+  }
+
+  if (typeof args.operation !== 'string' || !OPERATIONS.hasOwnProperty(args.operation)) {
+    throw new Error(`Unsupported operation: ${args.operation}`);
+  }
+
+  if (args.operation === 'divide' && args.b === 0) {
+    throw new Error('Division by zero is not allowed');
+  }
